import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.CchDE9cb.js";const u=JSON.parse('{"title":"Security overview","description":"The security defaults CapacityLens ships with, where the detailed evidence lives, and how to report a vulnerability.","frontmatter":{"title":"Security overview","description":"The security defaults CapacityLens ships with, where the detailed evidence lives, and how to report a vulnerability."},"headers":[],"relativePath":"security/index.md","filePath":"security/index.md","lastUpdated":null}'),n={name:"security/index.md"};function s(o,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="security-overview" tabindex="-1">Security overview <a class="header-anchor" href="#security-overview" aria-label="Permalink to &quot;Security overview&quot;">​</a></h1><p>This page is for anyone evaluating or operating CapacityLens who wants to know what protects their data without reading the source code. It summarises the defaults, points to the detailed evidence for anyone who needs it, and explains how to report a problem.</p><h2 id="what-s-on-by-default" tabindex="-1">What&#39;s on by default <a class="header-anchor" href="#what-s-on-by-default" aria-label="Permalink to &quot;What&#39;s on by default&quot;">​</a></h2><ul><li><strong>Sign-in.</strong> Password sign-in checks new and changed passwords against the Have I Been Pwned breached-password list before accepting them, and stores them with a modern, slow hashing algorithm. Optional <a href="/capacitylens/company-login/">company login</a> (single sign-on through your identity provider) is available as a first-class alternative.</li><li><strong>Multi-factor sign-in.</strong> An operator can require TOTP (a six-digit code from an authenticator app) for every password identity. It is opt-in, not on by default, and is turned on through <a href="/capacitylens/self-hosting/configuration">server configuration</a>.</li><li><strong>Sessions.</strong> A signed-in session lasts twelve hours at most and expires after thirty minutes of inactivity. The session cookie is host-only, so it&#39;s confined to your exact CapacityLens address, and it&#39;s held back from cross-site background requests — it&#39;s only sent on the top-level return from your identity provider during company login. People can see and revoke their own sessions, and an administrator can revoke a teammate&#39;s.</li><li><strong>Isolation between companies.</strong> Every request checks the signed-in person&#39;s membership and role in that specific company before it can read or change anything, so one company&#39;s data never leaks into another&#39;s.</li><li><strong>No tracking.</strong> CapacityLens ships with no product analytics, advertising or crash-reporting service. See <a href="/capacitylens/security/privacy">Privacy</a> for exactly what is stored and where.</li></ul><p>These are the defaults for the self-hosted, open-source application. An operator&#39;s own configuration, network setup and backup policy also matter — see <a href="/capacitylens/self-hosting/">Self-hosting</a> for the deployment side of the picture.</p><h2 id="where-the-detailed-evidence-lives" tabindex="-1">Where the detailed evidence lives <a class="header-anchor" href="#where-the-detailed-evidence-lives" aria-label="Permalink to &quot;Where the detailed evidence lives&quot;">​</a></h2><p>The bullets above are a summary. The full, dated evidence — what was reviewed, what passed, what is only partial, and what is out of scope — lives in the compliance artifacts. Start at <a href="/capacitylens/security/reviews">Reviews and compliance</a> for an index of all of them, including the OWASP ASVS 5.0.0 ledger, the security review, the threat model, the control inventories and the mutation-testing reviews.</p><h2 id="report-a-vulnerability" tabindex="-1">Report a vulnerability <a class="header-anchor" href="#report-a-vulnerability" aria-label="Permalink to &quot;Report a vulnerability&quot;">​</a></h2><p>CapacityLens has a published <a href="https://github.com/Kevinjohn/capacitylens/blob/main/SECURITY.md" target="_blank" rel="noreferrer">security policy</a> on GitHub. In short: use <a href="https://github.com/Kevinjohn/capacitylens/security/advisories/new" target="_blank" rel="noreferrer">GitHub private vulnerability reporting</a> rather than a public issue, discussion or pull request, and include the affected version/commit, prerequisites, reproduction steps and impact. The maintainer aims to acknowledge reports within five working days. Read the full policy for scope, response process and what is out of scope.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>Read <a href="/capacitylens/security/privacy">Privacy</a> for what data CapacityLens stores and what stays in the browser, or go straight to <a href="/capacitylens/security/reviews">Reviews and compliance</a> for the detailed evidence.</p>',11)])])}const y=t(n,[["render",s]]);export{u as __pageData,y as default};
